<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Asset Health · UNIFCO</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>:root{font-family:'Cairo',sans-serif;--navy:#06275c;--navy2:#071f4d;--red:#e20b24;--green:#168a55;--bg:#f5f7fa;--line:#dfe6ee;--muted:#708095}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--navy2)}a{text-decoration:none;color:inherit}.top{height:70px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 26px;gap:10px}.brand{font-size:20px;font-weight:900}.spacer{flex:1}.btn{display:inline-flex;padding:9px 13px;border-radius:8px;background:var(--navy);color:#fff;font-size:10px;font-weight:800;border:0}.btn.secondary{background:#edf3f8;color:var(--navy)}.wrap{max-width:1350px;margin:auto;padding:22px}.hero{background:linear-gradient(135deg,#071f4d,#123d72);color:#fff;border-radius:16px;padding:22px}.hero h1{margin:0 0 5px}.hero p{margin:0;color:#cad8e9;font-size:10px}.filters{display:grid;grid-template-columns:1fr 1fr auto;gap:9px;margin-top:14px}.filters label{font-size:9px}.filters select{width:100%;padding:9px;border-radius:7px}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:14px 0}.kpi,.box{background:#fff;border:1px solid var(--line);border-radius:12px}.kpi{padding:14px}.kpi b{display:block;font-size:20px}.kpi span{font-size:9px;color:var(--muted)}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px}.box{padding:17px}.box h3{margin:0 0 12px;font-size:14px}.health{display:inline-flex;padding:4px 7px;border-radius:999px;background:#e8f6ef;color:#176a43;font-size:8px;font-weight:800}.health.WATCH{background:#fff4df;color:#946000}.health.ATTENTION,.health.CRITICAL{background:#fdebed;color:#b42239}.item{padding:9px 0;border-bottom:1px solid #edf1f5;font-size:10px}.warn{color:#946000;font-weight:800}.bad{color:#b42239;font-weight:800}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse;font-size:10px}.table th,.table td{padding:9px;border-bottom:1px solid #edf1f5;text-align:left;white-space:nowrap}.table th{font-size:9px;color:var(--muted)}@media(max-width:850px){.kpis{grid-template-columns:1fr 1fr}.grid2,.filters{grid-template-columns:1fr}}@media(max-width:500px){.kpis{grid-template-columns:1fr}.wrap{padding:12px}}</style></head><body><header class="top"><div class="brand">UNIFCO</div><div class="spacer"></div><a class="btn secondary" href="{{ route('customer.section','assets') }}">Assets · الأصول</a><a class="btn secondary" href="{{ route('customer.portal') }}">Dashboard</a></header><main class="wrap"><section class="hero"><h1>Asset Health Portfolio · صحة الأصول</h1><p>Read-only lifecycle, reliability and maintenance view for your facilities. Internal UNIFCO costs and purchasing data are not displayed.</p><form class="filters" method="GET"><label>Site · الموقع<select name="site_id"><option value="">All Sites</option>@foreach($sites as $s)<option value="{{ $s->id }}" @selected($siteId==$s->id)>{{ $s->site_code }} · {{ $s->name }}</option>@endforeach</select></label><label>Contract · العقد<select name="contract_id"><option value="">All Contracts</option>@foreach($contracts as $c)<option value="{{ $c->id }}" @selected($contractId==$c->id)>{{ $c->contract_no }} · {{ $c->title }}</option>@endforeach</select></label><label style="align-self:end"><button class="btn">Apply</button></label></form></section><section class="kpis"><div class="kpi"><b>{{ $metrics['total'] }}</b><span>Total Assets · إجمالي الأصول</span></div><div class="kpi"><b>{{ $metrics['average']===null?'—':$metrics['average'].'/100' }}</b><span>Average Health · متوسط الصحة</span></div><div class="kpi"><b>{{ $metrics['availability'] }}%</b><span>Running Availability · الجاهزية</span></div><div class="kpi"><b>{{ $metrics['critical'] }}</b><span>Needs Attention · يحتاج متابعة</span></div><div class="kpi"><b>{{ $metrics['overduePm'] }}</b><span>Overdue PM · صيانة متأخرة</span></div><div class="kpi"><b>{{ $metrics['failures30'] }}</b><span>Failures 30 Days · أعطال 30 يوم</span></div><div class="kpi"><b>{{ $metrics['replacement'] }}</b><span>Replacement Planning · تخطيط إحلال</span></div><div class="kpi"><b>{{ $reorderAlerts->count() }}</b><span>Parts Availability Alerts · تنبيهات قطع الغيار</span></div></section><div class="grid2"><section class="box"><h3>Lifecycle Recommendations · توصيات دورة الحياة</h3>@forelse($recommendations as $r)<div class="item"><strong><a href="{{ route('customer.asset.show',$r->id) }}">{{ $r->asset_code }} · {{ $r->name }}</a></strong><br><span>{{ $r->site ?: 'No site' }}</span> · <span class="health {{ $r->health_band }}">{{ $r->health_score ?? '—' }} · {{ $r->health_band }}</span> · <span class="{{ $r->recommendation==='PLAN_REPLACEMENT'?'bad':'warn' }}">{{ str_replace('_',' ',$r->recommendation) }}</span><br><small>{{ $r->reason }}</small></div>@empty<p>No lifecycle action is currently required.</p>@endforelse</section><section class="box"><h3>Spare Parts Availability · توفر قطع الغيار</h3>@forelse($reorderAlerts as $a)<div class="item"><strong>{{ $a->asset_code }} · {{ $a->asset_name }}</strong><br><span>{{ $a->item_code }} · {{ $a->item_name }}</span> · <span class="{{ $a->computed_alert_status==='OUT_OF_STOCK'?'bad':'warn' }}">{{ str_replace('_',' ',$a->computed_alert_status) }}</span><br><small>Available: {{ number_format($a->available_quantity,2) }} {{ $a->uom }} · Reorder level: {{ number_format((float)$a->reorder_level,2) }}</small></div>@empty<p>No spare parts availability alerts.</p>@endforelse</section></div><section class="box" style="margin-top:14px"><h3>Spare Parts Consumption · استهلاك قطع الغيار · 12 Months</h3><div class="table-wrap"><table class="table"><thead><tr><th>Part</th><th>Description</th><th>Consumed Quantity</th><th>Work Orders</th></tr></thead><tbody>@forelse($consumption as $c)<tr><td><strong>{{ $c->item_code }}</strong></td><td>{{ $c->item_name }}</td><td>{{ number_format((float)$c->total_quantity,2) }} {{ $c->uom }}</td><td>{{ $c->work_order_count }}</td></tr>@empty<tr><td colspan="4">No spare parts consumption in this scope.</td></tr>@endforelse</tbody></table></div><p style="font-size:9px;color:var(--muted)">Internal purchasing cost, supplier pricing and labor cost are not displayed.</p></section><section class="box" style="margin-top:14px"><h3>Asset Health Register · سجل صحة الأصول</h3><div class="table-wrap"><table class="table"><thead><tr><th>Asset</th><th>Site</th><th>Operational</th><th>Health</th><th>Remaining Life</th><th>Recommendation</th></tr></thead><tbody>@forelse($assets as $a)<tr><td><a href="{{ route('customer.asset.show',$a) }}"><strong>{{ $a->asset_code }}</strong></a><br><small>{{ $a->name }}</small></td><td>{{ $a->site?->name ?: '—' }}</td><td>{{ $a->operational_status }}</td><td><span class="health {{ $a->health_band }}">{{ $a->health_score ?? '—' }} · {{ $a->health_band ?: 'PENDING' }}</span></td><td>{{ $a->remaining_life_months===null?'—':round($a->remaining_life_months/12,1).' y' }}</td><td>{{ str_replace('_',' ',$a->replacement_recommendation ?: 'PENDING') }}</td></tr>@empty<tr><td colspan="6">No assets found.</td></tr>@endforelse</tbody></table></div></section></main></body></html>